  else { ndfs++; ok=exact(vpar); 
     if(ok){ if(!verify()){fprintf(stderr,"VERIFYFAIL DFS\n"); exit(2);} }
     if(hardf){ fprintf(hardf,"%d %lld",ok,nodes); for(int j=2;j<=n;j++) fprintf(hardf," %d",vpar[j]); fputc('\n',hardf);} }
  if(!ok){ nfail++; fprintf(stderr,"NOSEG n=%d:",n); for(int j=2;j<=n;j++) fprintf(stderr," %d",vpar[j]); fprintf(stderr,"\n"); }
